{"code": "export async function main(input) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const out = [];
  for (const i of issues) {
    if (i.count < 100) continue;
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    out.push({ shortId: i.shortId, count: i.count, status: i.status, project: i.project, nEvents: events.length, events: events.slice(0, 5) });
  }
  return { total: issues.length, statuses: issues.map(i=>i.status), out };
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const out = [];
