  }
  return { total: issues.length, all: issues.map(i=>({shortId:i.shortId,count:i.count,status:i.status,project:i.project})), out };
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const detail = [];
  for (const i of issues) {
    if (i.count < 100) continue;
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    const sortedDesc = [...events].sort((a, b) => b.timestamp.localeCompare(a.timestamp));
    detail.push({
      shortId: i.shortId,
      lastSeen: i.lastSeen,
      events,
      isDesc: JSON.stringify(sortedDesc.map(e => e.id)) === JSON.stringify(events.map(e => e.id)),
    });
  }
  return detail;
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const result: { shortId: string; count: number; status: string; latestRelease: string | null }[] = [];
  for (const i of issues) {
    if (i.count < 100) continue;
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    let newest: { timestamp: string; release: string } | null = null;
    for (const e of events) {
      if (!newest || e.timestamp > newest.timestamp) newest = e;
    }
    result.push({
      shortId: i.shortId,
      count: i.count,
      status: i.status,
      latestRelease: newest ? newest.release : null,
    });
  }
  result.sort((a, b) => b.count - a.count);
  return result;
}"}
